import{_ as h,C as n,o as d,c as i,a2 as a,b as E,w as r,a as o,E as s,a3 as l}from"./chunks/framework.CFuv5BrO.js";const _=JSON.parse('{"title":"Hearth OS 定时任务设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/定时任务设计说明.md","filePath":"architecture/定时任务设计说明.md","lastUpdated":null}'),A={name:"architecture/定时任务设计说明.md"};function B(b,t,u,c,p,g){const e=n("Mermaid");return d(),i("div",null,[t[2]||(t[2]=a('<h1 id="hearth-os-定时任务设计说明" tabindex="-1">Hearth OS 定时任务设计说明 <a class="header-anchor" href="#hearth-os-定时任务设计说明" aria-label="Permalink to &quot;Hearth OS 定时任务设计说明&quot;">​</a></h1><blockquote><p>本文根据项目源码整理，未参考 docs 目录下的设计文档，也不包含项目具体代码。 主要依据：服务端 schedules.ts、scheduler.ts、app.ts，数据层 eventlog/database.ts，类型定义 core/types.ts，前端 SchedulesPage.tsx 与 App.tsx，以及对应的单元测试。 整理日期：2026-11-13</p></blockquote><hr><h2 id="速览-三句话" tabindex="-1">速览（三句话） <a class="header-anchor" href="#速览-三句话" aria-label="Permalink to &quot;速览（三句话）&quot;">​</a></h2><ol><li>定时任务不是「给每条计划挂一个 Cron 定时器」，而是<strong>把下次运行时间存进数据库，用一个 30 秒的轮询去扫描到期的计划</strong>。</li><li>到点后它只做一件事：<strong>幂等地创建一条运行记录和一个普通任务，并留下投递回执</strong>，真正的执行交给下游的任务执行调度器。</li><li>一旦投递结果不确定或连续失败，它<strong>宁可暂停计划并生成人工待办，也不盲目自动重试</strong>，全程可追溯、可对账。</li></ol><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li>一、先分清两个「Scheduler」</li><li>二、模块地图</li><li>三、数据模型：两张表</li><li>四、时钟是怎么走的</li><li>五、错过时间怎么办：三种补跑策略</li><li>六、触发瞬间的可靠性防线</li><li>七、失败治理：冷却与自动暂停</li><li>八、状态回流与用户界面</li><li>九、与其他后台周期任务的区别</li><li>十、设计取舍与需要注意的边界</li><li>十一、一句话总结</li><li>附录 A：关键默认值速查</li><li>附录 B：源码索引</li></ul><hr><h2 id="一、先分清两个「scheduler」" tabindex="-1">一、先分清两个「Scheduler」 <a class="header-anchor" href="#一、先分清两个「scheduler」" aria-label="Permalink to &quot;一、先分清两个「Scheduler」&quot;">​</a></h2><p>项目里有两个名字相近、职责完全不同的模块，这是理解整套设计的第一道门槛。</p><table tabindex="0"><thead><tr><th></th><th>ScheduleService（schedules.ts）</th><th>HearthScheduler（scheduler.ts）</th></tr></thead><tbody><tr><td>回答的问题</td><td><strong>什么时候该跑</strong></td><td><strong>怎么把已创建的任务跑起来</strong></td></tr><tr><td>是不是定时任务</td><td>是，本文的主角</td><td>不是，是任务执行调度器</td></tr><tr><td>驱动方式</td><td>30 秒轮询数据库</td><td>事件驱动：任务创建或更新时唤醒循环</td></tr><tr><td>主要产出</td><td>运行记录、任务、投递回执</td><td>执行器进程、任务状态、产物</td></tr><tr><td>用户可配置</td><td>是，页面可增删改查</td><td>否，属于系统内部能力</td></tr></tbody></table><p>两者的交界点只有一个：定时任务到点后<strong>创建一个普通任务</strong>，任务创建事件会唤醒执行调度器，后续排队、并发控制、执行、审批、产物回收都由后者负责。这种「触发与执行解耦」让定时模块可以专注于时间和投递可靠性。</p><h3 id="_1-1-整体链路一览" tabindex="-1">1.1 整体链路一览 <a class="header-anchor" href="#_1-1-整体链路一览" aria-label="Permalink to &quot;1.1 整体链路一览&quot;">​</a></h3>',14)),(d(),E(l,null,{default:r(()=>[s(e,{id:"mermaid-185",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%94%A8%E6%88%B7%E5%9C%A8%E9%A1%B5%E9%9D%A2%E9%85%8D%E7%BD%AE%E8%AE%A1%E5%88%92%3Cbr%2F%3ECron%20%2F%20%E6%97%B6%E5%8C%BA%20%2F%20%E6%8F%90%E7%A4%BA%E8%AF%8D%20%2F%20%E6%89%A7%E8%A1%8C%E5%99%A8%22%5D%20--%3E%20B%5B%22ScheduleService%20%E6%A0%A1%E9%AA%8C%E5%B9%B6%E8%90%BD%E5%BA%93%3Cbr%2F%3E%E7%AE%97%E5%87%BA%E4%B8%8B%E6%AC%A1%E8%BF%90%E8%A1%8C%E6%97%B6%E9%97%B4%22%5D%0A%20%20B%20--%3E%20C%5B(%22SQLite%20%E4%B8%A4%E5%BC%A0%E8%A1%A8%3Cbr%2F%3E%E8%AE%A1%E5%88%92%E8%A1%A8%20%2B%20%E8%BF%90%E8%A1%8C%E8%AE%B0%E5%BD%95%E8%A1%A8%22)%5D%0A%20%20C%20--%3E%20D%5B%2230%20%E7%A7%92%E8%BD%AE%E8%AF%A2%E6%89%AB%E6%8F%8F%E5%88%B0%E6%9C%9F%E8%AE%A1%E5%88%92%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%A1%A5%E8%B7%91%E7%AD%96%E7%95%A5%20%2B%20%E4%BC%98%E5%85%88%E7%BA%A7%E6%8E%92%E5%BA%8F%20%2B%20%E6%AF%8F%E8%BD%AE%E9%A2%84%E7%AE%97%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%B9%82%E7%AD%89%E8%A7%A6%E5%8F%91%3Cbr%2F%3E%E8%BF%90%E8%A1%8C%E8%AE%B0%E5%BD%95%20%E2%86%92%20%E4%BB%BB%E5%8A%A1%20%E2%86%92%20%E6%8A%95%E9%80%92%E5%9B%9E%E6%89%A7%22%5D%0A%20%20F%20--%3E%20G%5B%22HearthScheduler%20%E8%A2%AB%E4%BB%BB%E5%8A%A1%E4%BA%8B%E4%BB%B6%E5%94%A4%E9%86%92%3Cbr%2F%3E%E6%8C%89%E5%B9%B6%E5%8F%91%E4%B8%8A%E9%99%90%E6%89%A7%E8%A1%8C%22%5D%0A%20%20G%20--%3E%20H%5B%22%E4%BB%BB%E5%8A%A1%E7%8A%B6%E6%80%81%E6%98%A0%E5%B0%84%E5%9B%9E%E8%BF%90%E8%A1%8C%E8%AE%B0%E5%BD%95%22%5D%0A%20%20H%20--%3E%20I%5B%22%E4%BA%8B%E4%BB%B6%E6%80%BB%E7%BA%BF%20%2F%20SSE%20%E6%8E%A8%E9%80%81%E5%89%8D%E7%AB%AF%22%5D%0A%20%20I%20--%3E%20C%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=a('<hr><h2 id="二、模块地图" tabindex="-1">二、模块地图 <a class="header-anchor" href="#二、模块地图" aria-label="Permalink to &quot;二、模块地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>职责</th></tr></thead><tbody><tr><td>core/types.ts</td><td>定义计划、运行记录、状态枚举、补跑策略等数据契约</td></tr><tr><td>eventlog/database.ts</td><td>两张 SQLite 表、唯一约束与索引、字段迁移、读写方法</td></tr><tr><td>schedules.ts</td><td>全部业务逻辑：参数校验、轮询、补跑、幂等投递、失败治理、事件发布</td></tr><tr><td>app.ts</td><td>服务装配、REST 接口、启动与关闭时的生命周期管理</td></tr><tr><td>SchedulesPage.tsx / App.tsx</td><td>配置表单、运行历史、事件驱动的实时刷新</td></tr><tr><td>scheduler.ts</td><td>下游执行层，消费定时任务创建出来的任务</td></tr></tbody></table><p>服务启动时，定时服务是<strong>无条件启动</strong>的（不受那些可选的后台开关影响），并且启动时立刻执行一次扫描；关闭服务时会在 onClose 钩子中停止轮询、取消事件订阅。</p><hr><h2 id="三、数据模型-两张表" tabindex="-1">三、数据模型：两张表 <a class="header-anchor" href="#三、数据模型-两张表" aria-label="Permalink to &quot;三、数据模型：两张表&quot;">​</a></h2><h3 id="_3-1-计划表-scheduled-jobs" tabindex="-1">3.1 计划表（scheduled_jobs） <a class="header-anchor" href="#_3-1-计划表-scheduled-jobs" aria-label="Permalink to &quot;3.1 计划表（scheduled_jobs）&quot;">​</a></h3><p>一条计划就是「在什么时间、用什么执行器、把什么提示词交给谁去办」，字段可以分成四组：</p><ul><li><strong>跑什么</strong>：名称、固定提示词、绑定的专属对话、执行器、审批模式、任务类型。</li><li><strong>何时跑</strong>：Cron 表达式、时区（默认 Asia/Shanghai）、启用开关、下次运行时间。</li><li><strong>跑过头了怎么办</strong>：补跑策略、单次补跑上限（默认 3，可配 1–20）、优先级（默认 5，可配 0–100）。</li><li><strong>自我保护与留痕</strong>：上次运行时间 / 任务 / 状态、连续失败次数、冷却截止时间、暂停原因、跑完是否删除、创建与更新时间。</li></ul><p>默认值：执行器为内置执行器、审批模式为「必要时审批」、任务类型为通用、补跑策略为 run_once、启用状态为开。</p><h3 id="_3-2-运行记录表-scheduled-job-runs" tabindex="-1">3.2 运行记录表（scheduled_job_runs） <a class="header-anchor" href="#_3-2-运行记录表-scheduled-job-runs" aria-label="Permalink to &quot;3.2 运行记录表（scheduled_job_runs）&quot;">​</a></h3><p>每一个「计划时间点」对应一条记录，用于回答「这一轮到底发生了什么」：计划时间点、关联任务、关联投递效果、幂等键、尝试次数、回执、失败分类、状态、错误说明。</p><p><strong>最关键的设计</strong>是表上的唯一约束：<strong>计划 ID + 计划时间点</strong> 只能有一条记录。这是防重复触发的数据库兜底，比任何内存标志都可靠。此外还有针对「启用状态 + 下次运行时间」的索引，服务于到期扫描。</p><h3 id="_3-3-状态" tabindex="-1">3.3 状态 <a class="header-anchor" href="#_3-3-状态" aria-label="Permalink to &quot;3.3 状态&quot;">​</a></h3><p>运行记录共 6 种状态：排队中、执行中、已完成、失败、已跳过、已取消。任务本身的状态会在执行过程中被映射回这 6 种状态（见第八节）。</p><hr><h2 id="四、时钟是怎么走的" tabindex="-1">四、时钟是怎么走的 <a class="header-anchor" href="#四、时钟是怎么走的" aria-label="Permalink to &quot;四、时钟是怎么走的&quot;">​</a></h2><h3 id="_4-1-核心思路-cron-库只当计算器-不当闹钟" tabindex="-1">4.1 核心思路：Cron 库只当计算器，不当闹钟 <a class="header-anchor" href="#_4-1-核心思路-cron-库只当计算器-不当闹钟" aria-label="Permalink to &quot;4.1 核心思路：Cron 库只当计算器，不当闹钟&quot;">​</a></h3><p>代码里没有为每条计划注册常驻定时器。Cron 库被以「暂停模式」创建，只用于两件纯计算的事：</p><ul><li>创建或修改计划时，校验 Cron 表达式是否合法、时区是否有效（时区用国际化时间格式接口校验）；</li><li>从某个时间点算出「下一次该跑是什么时候」，算完立即释放实例。</li></ul><p>真正推进时间的，是定时服务里<strong>唯一一个 30 秒间隔的轮询</strong>。服务启动时会立刻先跑一次，随后每 30 秒重复。</p><h3 id="_4-2-一次轮询的完整步骤" tabindex="-1">4.2 一次轮询的完整步骤 <a class="header-anchor" href="#_4-2-一次轮询的完整步骤" aria-label="Permalink to &quot;4.2 一次轮询的完整步骤&quot;">​</a></h3>',22)),(d(),E(l,null,{default:r(()=>[s(e,{id:"mermaid-333",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%89%AB%E6%8F%8F%E5%88%B0%E6%9C%9F%E8%AE%A1%E5%88%92%3Cbr%2F%3E%E5%B7%B2%E5%90%AF%E7%94%A8%20%2B%20%E5%B7%B2%E5%88%B0%E7%82%B9%20%2B%20%E4%B8%8D%E5%9C%A8%E5%86%B7%E5%8D%B4%E6%9C%9F%22%5D%20--%3E%20B%5B%22%E6%8C%89%E4%BC%98%E5%85%88%E7%BA%A7%20%E2%86%92%20%E5%88%B0%E6%9C%9F%E6%97%B6%E9%97%B4%E6%8E%92%E5%BA%8F%3Cbr%2F%3E%E6%AF%8F%E8%BD%AE%E5%85%B1%E4%BA%AB%E9%A2%84%E7%AE%97%E6%9C%80%E5%A4%9A%2010%20%E6%AC%A1%22%5D%0A%20%20B%20--%3E%20C%7B%22%E8%AF%A5%E8%AE%A1%E5%88%92%E7%9A%84%E8%A1%A5%E8%B7%91%E7%AD%96%E7%95%A5%22%7D%0A%20%20C%20--%3E%7Cskip%7C%20D%5B%22%E9%80%BE%E6%9C%9F%E8%B6%85%E8%BF%87%205%20%E5%88%86%E9%92%9F%20%E2%86%92%20%E8%AE%B0%E4%B8%80%E6%9D%A1%E5%B7%B2%E8%B7%B3%E8%BF%87%22%5D%0A%20%20C%20--%3E%7Crun_once%20%E9%BB%98%E8%AE%A4%7C%20E%5B%2224%20%E5%B0%8F%E6%97%B6%E5%AE%BD%E9%99%90%E5%86%85%3Cbr%2F%3E%E5%8F%AA%E8%A1%A5%E6%9C%80%E8%BF%91%E4%B8%80%E6%AC%A1%22%5D%0A%20%20C%20--%3E%7Crun_all_bounded%7C%20F%5B%22%E6%8C%89%E4%B8%8A%E9%99%90%E5%88%86%E6%89%B9%E8%A1%A5%E8%B7%91%22%5D%0A%20%20D%20--%3E%20G%5B%22%E5%B9%82%E7%AD%89%E6%8A%95%E9%80%92%3Cbr%2F%3E%E8%BF%90%E8%A1%8C%E8%AE%B0%E5%BD%95%20%E2%86%92%20%E4%BB%BB%E5%8A%A1%20%E2%86%92%20%E6%8F%90%E4%BA%A4%E5%9B%9E%E6%89%A7%22%5D%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A%20%20G%20--%3E%20H%7B%22%E6%8A%95%E9%80%92%E7%BB%93%E6%9E%9C%22%7D%0A%20%20H%20--%3E%7C%E6%88%90%E5%8A%9F%7C%20I%5B%22%E6%8E%A8%E8%BF%9B%E4%B8%8B%E6%AC%A1%E8%BF%90%E8%A1%8C%E6%97%B6%E9%97%B4%22%5D%0A%20%20H%20--%3E%7C%E4%B8%80%E8%88%AC%E5%A4%B1%E8%B4%A5%7C%20J%5B%22%E6%8C%87%E6%95%B0%E9%80%80%E9%81%BF%E5%86%B7%E5%8D%B4%EF%BC%8C%E7%AD%89%E4%B8%8B%E8%BD%AE%E5%86%8D%E8%AF%95%22%5D%0A%20%20H%20--%3E%7C%E8%BF%9E%E7%BB%AD%E5%A4%B1%E8%B4%A5%20%2F%20%E8%87%B4%E5%91%BD%20%2F%20%E4%B8%8D%E7%A1%AE%E5%AE%9A%7C%20K%5B%22%E8%87%AA%E5%8A%A8%E6%9A%82%E5%81%9C%20%2B%20%E7%94%9F%E6%88%90%E4%BA%BA%E5%B7%A5%E5%BE%85%E5%8A%9E%22%5D%0A"})]),fallback:r(()=>[...t[1]||(t[1]=[o(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=a('<p>具体步骤展开：</p><ol><li><strong>筛选到期</strong>：已启用、有下次运行时间、时间已到、且不在冷却期内的计划。</li><li><strong>排序</strong>：先按优先级（数值小的优先），再按到期时间先后。</li><li><strong>限量</strong>：设一个共享的每轮预算（默认最多触发 10 次，可配置），用一个「正在轮询」标志防止重入。</li><li><strong>回溯漏掉的周期</strong>：从上次的下次运行时间开始，用带时区的 Cron 逐个往后推算，最多扫描 2000 个时间点，并对结果去重。单元测试专门覆盖了夏令时跳变与回拨，保证同一个墙钟时间只跑一次。</li><li><strong>决定补跑方式</strong>：按计划的补跑策略选择要真正触发哪些时间点（见第五节）。</li><li><strong>逐个触发</strong>：对选中的时间点执行幂等投递（见第六节），并把下次运行时间推进到未来。</li></ol><h3 id="_4-3-为什么这样设计" tabindex="-1">4.3 为什么这样设计 <a class="header-anchor" href="#_4-3-为什么这样设计" aria-label="Permalink to &quot;4.3 为什么这样设计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>收益</th><th>原因</th></tr></thead><tbody><tr><td>重启不丢计划</td><td>下次运行时间是数据库字段，不是内存里的定时器</td></tr><tr><td>暂停 / 恢复 / 改期很简单</td><td>只是改字段、重算时间，不需要增删定时器</td></tr><tr><td>停机期间可以补跑</td><td>漏掉的周期能从旧时间点推算出来</td></tr><tr><td>不重复触发</td><td>唯一约束 + 幂等键 + 防重入标志三重保障</td></tr><tr><td>不会挤爆执行器</td><td>每轮预算限制 + 优先级排序</td></tr></tbody></table><p>代价是<strong>触发精度为 30 秒级</strong>，且这是一个面向单机本地服务的设计。对「每天九点生成一份简报」这类场景完全够用。</p><hr><h2 id="五、错过时间怎么办-三种补跑策略" tabindex="-1">五、错过时间怎么办：三种补跑策略 <a class="header-anchor" href="#五、错过时间怎么办-三种补跑策略" aria-label="Permalink to &quot;五、错过时间怎么办：三种补跑策略&quot;">​</a></h2><p>服务停机、机器休眠、执行器忙碌都可能让计划错过原定时间。项目提供三种策略，由用户在创建计划时选择：</p><table tabindex="0"><thead><tr><th>策略</th><th>行为</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>skip</strong></td><td>只要逾期超过约 5 分钟容差，就记一条「已跳过」，直接推进到下一次</td><td>过期就没有意义的任务，如整点快讯</td></tr><tr><td><strong>run_once</strong>（默认）</td><td>错过不超过 24 小时宽限，只补最近那一次，折叠掉中间所有周期</td><td>日报、例行检查，补一次即可</td></tr><tr><td><strong>run_all_bounded</strong></td><td>在宽限期内按配置上限分批补跑（默认 3 次），且仍受每轮预算约束</td><td>不能漏的周期性采集</td></tr></tbody></table><p>三条路径的共同行为：</p><ul><li>被跳过的周期也会<strong>写一条运行记录</strong>，说明跳过原因，不会凭空消失；</li><li>在计划自己的专属对话里留一条说明消息；</li><li>把下次运行时间推进到<strong>未来</strong>，绝不会让计划卡在过去反复触发。</li></ul><hr><h2 id="六、触发瞬间的可靠性防线" tabindex="-1">六、触发瞬间的可靠性防线 <a class="header-anchor" href="#六、触发瞬间的可靠性防线" aria-label="Permalink to &quot;六、触发瞬间的可靠性防线&quot;">​</a></h2><p>这是整套设计里最讲究的部分，可以概括为「先留痕、再投递、不确定就停手」。</p><p><strong>第一道：幂等</strong></p><p>幂等键由「计划 ID + 计划时间点」拼成；运行表上有对应的唯一约束；写入运行记录时如果发现同一时间点已有记录，就直接放弃本次触发。因此服务重启、轮询重叠、用户手动点「立即运行」都不会重复创建任务。</p><p><strong>第二道：固定投递顺序</strong></p><p>先写运行记录（排队态）→ 检查执行器是否可用（不可用时记「已跳过」并带原因）→ 创建任务 → 生成一条标准投递效果记录（类型为 schedule.trigger，只投一次、永不重放）→ 提交回执 → 回写运行记录与计划的上次结果。</p><p><strong>第三道：结果不确定时不重试</strong></p><p>如果回执写入出错，服务会先查是否已经存在「已提交」的回执：查得到就复用它完成本次运行；查不到就把效果标记为「不确定」，<strong>立即暂停计划</strong>，在对话里提示用户核对任务与效果记录的真实状态，并生成一条去重的人工待办。原则是：宁可等人确认，也不冒险重复投递。</p><p><strong>第四道：一次性计划的安全删除</strong></p><p>勾选「跑完删除」的计划，只有在拿到「已提交」回执后才会被删除；否则改为暂停等待确认。删除计划会连带删除它的运行记录，但<strong>保留专属对话和已产生的任务</strong>，不会把历史痕迹一起抹掉。</p><p><strong>第五道：全程可追溯</strong></p><p>每条计划创建时都会自动建立一个专属对话；触发成功、跳过、失败、暂停都会在这个对话里留下消息，用户可以直接从运行记录跳转到对应任务详情。</p><hr><h2 id="七、失败治理-冷却与自动暂停" tabindex="-1">七、失败治理：冷却与自动暂停 <a class="header-anchor" href="#七、失败治理-冷却与自动暂停" aria-label="Permalink to &quot;七、失败治理：冷却与自动暂停&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>处理方式</th></tr></thead><tbody><tr><td>执行器不可用</td><td>本次记为「已跳过」，不影响其他计划</td></tr><tr><td>一般失败（如临时错误）</td><td>进入<strong>指数退避冷却</strong>：5 分钟起，上限 1 小时；冷却期内该计划不参与扫描</td></tr><tr><td>认证失败、权限被拒、投递结果不确定</td><td>视为<strong>致命错误，立即暂停</strong></td></tr><tr><td>连续失败达到上限（默认 3 次）</td><td>自动禁用计划、清空下次运行时间、写下暂停原因、生成一条去重的人工待办</td></tr><tr><td>用户重新启用</td><td>清零失败次数、冷却时间与暂停原因，重新计算下次运行时间</td></tr></tbody></table><p>待办带有去重键，同一个计划反复出问题不会刷出一堆重复提醒；凭据类问题会被标为更高优先级。</p><hr><h2 id="八、状态回流与用户界面" tabindex="-1">八、状态回流与用户界面 <a class="header-anchor" href="#八、状态回流与用户界面" aria-label="Permalink to &quot;八、状态回流与用户界面&quot;">​</a></h2><p><strong>状态回流</strong>：定时服务订阅任务更新事件，通过任务反查运行记录，把任务状态映射成运行记录状态——排队、运行或等待输入 / 审批归为「执行中」，完成、取消、失败各归其位——再回写计划的上次结果。这样定时任务自己不必跟踪执行进度。</p><p><strong>实时刷新</strong>：所有变更（计划创建 / 更新、运行记录创建 / 更新）都会追加进事件流，并经事件总线推送给前端的 SSE 连接；前端收到相关事件后刷新计划列表与运行历史。运行历史另有 10 秒轮询作为兜底。</p><p><strong>接口与界面</strong>：服务端提供计划的增删改查、立即运行、运行历史五类接口。页面侧提供常用 Cron 预设（每小时、每天九点、工作日九点、每周一、每月一日、高级自定义）、时区填写、启用开关、暂停 / 恢复、立即运行按钮，以及最近 20 次运行记录（含状态徽标、时间、错误或任务链接）。</p><hr><h2 id="九、与其他后台周期任务的区别" tabindex="-1">九、与其他后台周期任务的区别 <a class="header-anchor" href="#九、与其他后台周期任务的区别" aria-label="Permalink to &quot;九、与其他后台周期任务的区别&quot;">​</a></h2><p>系统里还有一批<strong>内置后台循环</strong>，它们是进程内固定间隔的定时器，不可由用户配置，和用户定时任务不是同一套机制：</p><table tabindex="0"><thead><tr><th>后台服务</th><th>默认间隔</th><th>大致职责</th></tr></thead><tbody><tr><td>维护服务</td><td>6 小时</td><td>例行维护</td></tr><tr><td>主动建议服务</td><td>5 分钟</td><td>生成主动提醒 / 建议</td></tr><tr><td>常驻意图服务</td><td>5 分钟</td><td>检查长期意图是否需要推进</td></tr><tr><td>看门狗</td><td>60 秒</td><td>健康与异常监控</td></tr><tr><td>技能整理服务</td><td>1 小时</td><td>技能包的整理与治理</td></tr></tbody></table><p>这些服务由启动参数分别控制开关，而用户定时任务始终随服务启动。</p><hr><h2 id="十、设计取舍与需要注意的边界" tabindex="-1">十、设计取舍与需要注意的边界 <a class="header-anchor" href="#十、设计取舍与需要注意的边界" aria-label="Permalink to &quot;十、设计取舍与需要注意的边界&quot;">​</a></h2><ul><li><strong>触发与执行彻底解耦</strong>：定时模块不关心任务怎么跑、用哪个执行器、要不要审批，只负责在正确的时间把任务可靠地交出去。</li><li><strong>数据库是唯一真相</strong>：计划、下次运行时间、运行记录、回执都落库，内存里只有轮询计数与防重入标志。</li><li><strong>出错时保守</strong>：不确定状态一律暂停并请人对账，不做自动重试，避免重复执行外部动作。</li><li><strong>全局停止开关的边界</strong>：开关停掉的是<strong>任务执行调度器</strong>，并没有停掉定时轮询时钟。停止期间到点的计划仍可能被投递成排队任务，等执行层恢复后再消费。这是从启动与开关代码能直接看出的取舍，值得留意。</li><li><strong>单机假设</strong>：轮询是单进程内的定时器；跨实例部署时的时间竞争并未在设计中专门处理（唯一约束能挡住重复运行记录，但不属于分布式调度方案）。</li><li><strong>精度取舍</strong>：30 秒级的触发延迟，换来了可持久化、可补跑、可暂停的实现。</li></ul><hr><h2 id="十一、一句话总结" tabindex="-1">十一、一句话总结 <a class="header-anchor" href="#十一、一句话总结" aria-label="Permalink to &quot;十一、一句话总结&quot;">​</a></h2><blockquote><p>用「数据库里的下次运行时间 + 30 秒轮询」代替常驻定时器，用「幂等键 + 唯一约束 + 投递回执」保证不重不漏，用「冷却、自动暂停、人工待办」兜住所有不确定，再把触发和执行干净地拆开——这就是这套定时任务的设计。</p></blockquote><hr><h2 id="附录-a-关键默认值速查" tabindex="-1">附录 A：关键默认值速查 <a class="header-anchor" href="#附录-a-关键默认值速查" aria-label="Permalink to &quot;附录 A：关键默认值速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>轮询间隔</td><td>30 秒</td><td>启动时立即先跑一次</td></tr><tr><td>每轮触发预算</td><td>10 次</td><td>所有到期计划共享，可配置</td></tr><tr><td>补跑策略</td><td>run_once</td><td>另有 skip、run_all_bounded</td></tr><tr><td>补跑宽限</td><td>24 小时</td><td>超过则跳过并记录原因</td></tr><tr><td>skip 容差</td><td>5 分钟</td><td>逾期超过即跳过</td></tr><tr><td>单次补跑次数上限</td><td>3 次</td><td>可配 1–20</td></tr><tr><td>到期时间点扫描上限</td><td>2000 个</td><td>防止长时间停机后的推算失控</td></tr><tr><td>优先级</td><td>5</td><td>可配 0–100，数值小者优先</td></tr><tr><td>失败冷却</td><td>5 分钟起</td><td>指数退避，上限 1 小时</td></tr><tr><td>连续失败暂停阈值</td><td>3 次</td><td>致命类错误立即暂停</td></tr><tr><td>默认时区</td><td>Asia/Shanghai</td><td>用国际化时间格式接口校验合法性</td></tr><tr><td>运行历史前端兜底刷新</td><td>10 秒</td><td>主通道为 SSE 事件推送</td></tr></tbody></table><hr><h2 id="附录-b-源码索引" tabindex="-1">附录 B：源码索引 <a class="header-anchor" href="#附录-b-源码索引" aria-label="Permalink to &quot;附录 B：源码索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>可核对的设计点</th></tr></thead><tbody><tr><td>apps/server/src/schedules.ts</td><td>参数校验、30 秒轮询、补跑策略、幂等触发、失败治理、事件发布</td></tr><tr><td>apps/server/src/scheduler.ts</td><td>执行层：事件唤醒循环、排队任务挑选、执行器并发上限（非定时模块）</td></tr><tr><td>apps/server/src/app.ts</td><td>服务装配、五个 REST 接口、启动 / 关闭时的 start 与 stop、全局停止开关</td></tr><tr><td>packages/eventlog/src/database.ts</td><td>两张表结构、唯一约束与索引、字段迁移、读写方法</td></tr><tr><td>packages/core/src/types.ts</td><td>计划与运行记录的数据契约、状态与补跑策略枚举</td></tr><tr><td>apps/web/src/pages/SchedulesPage.tsx</td><td>Cron 预设、启停、立即运行、运行历史展示</td></tr><tr><td>apps/web/src/App.tsx</td><td>订阅 schedule 相关事件并刷新查询</td></tr><tr><td>apps/server/src/schedules.test.ts</td><td>补跑、夏令时、幂等、冷却、自动暂停、一次性计划等用例</td></tr></tbody></table>',50))])}const F=h(A,[["render",B]]);export{_ as __pageData,F as default};
